def deduplicate(items):
    """Return one copy of each item, in first-seen order."""
    result = []
    for item in items:
        if item not in result:
            result.append(item)
    return result

import unittest
from dedup import deduplicate


class KeyedDeduplicateTests(unittest.TestCase):
    def test_casefold_key_preserves_first_displayed_value(self):
        self.assertEqual(
            deduplicate(["A", "a", "B", "A"], key=str.casefold),
            ["A", "B"],
        )

    def test_key_is_optional_and_original_behavior_remains(self):
        self.assertEqual(deduplicate(["b", "a", "b"]), ["b", "a"])

    def test_key_can_compare_unhashable_derived_values(self):
        values = [[1, 2], [1, 2], [2, 1]]
        self.assertEqual(
            deduplicate(values, key=lambda value: list(reversed(value))),
            [[1, 2], [2, 1]],
        )


if __name__ == "__main__":
    unittest.main()

def deduplicate(items, *, key=None):
    """Return first-seen items, optionally comparing them by key."""
    result = []
    seen_keys = []
    for item in items:
        comparison = item if key is None else key(item)
        if comparison not in seen_keys:
            seen_keys.append(comparison)
            result.append(item)
    return result
